// Parpadeo del LED del pin 13
void setup() {
  pinMode(13, OUTPUT);     // el pin 13 será salida
}

void loop() {               // se repite siempre
  digitalWrite(13, HIGH);  // enciende
  delay(1000);             // espera 1 s
  digitalWrite(13, LOW);   // apaga
  delay(1000);
}

#include <Servo.h>
Servo puerta;
const int TRIG = 7, ECHO = 6;  // distancia
const int VERDE = 4, ROJO = 5, ZUMB = 8;

long medirCm() {               // devuelve cm
  digitalWrite(TRIG, LOW);  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  return pulseIn(ECHO, HIGH) * 0.01723;
}

void setup() {
  puerta.attach(9);            // servo en el pin 9
  pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT);
  pinMode(VERDE, OUTPUT); pinMode(ROJO, OUTPUT);
  pinMode(ZUMB, OUTPUT);
  Serial.begin(9600);
}

